package com.acme.status

import io.ktor.client.HttpClient
import io.ktor.client.request.get
import io.ktor.http.isSuccess

class StatusChecker(private val client: HttpClient) {
    suspend fun check(endpoints: List<String>): Map<String, Boolean> {
        val result = mutableMapOf<String, Boolean>()
        for (url in endpoints) {
            result[url] = runCatching { client.get(url).status.isSuccess() }.getOrDefault(false)
        }
        return result
    }
}

