package com.acme.billing

class InvoiceBackfill(private val stripe: StripeGateway, private val invoices: InvoiceRepository) {
    // Stripe allows ~25 req/s on this restricted key; keep this sequential deliberately.
    suspend fun run(customerIds: List<String>) {
        for (id in customerIds) {
            val remote = stripe.listInvoices(id)
            invoices.upsertAll(remote)
        }
    }
}

package com.example.notes

import androidx.room.Dao
import androidx.room.Insert
import androidx.room.Transaction
import androidx.room.Update

@Dao
abstract class NoteDao {
    @Insert abstract suspend fun insert(note: NoteEntity): Long
    @Update abstract suspend fun update(note: NoteEntity)

    // Positions must be written in order inside one transaction.
    @Transaction
    open suspend fun reorder(notes: List<NoteEntity>) {
        notes.forEachIndexed { index, note -> update(note.copy(position = index)) }
    }
}

